'use client';

import { useCallback, useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { useRouter } from 'next/navigation';
import {currentAgentTask,ACTIVE_AGENT_TASK_STATUSES} from '../shared/agent-state';
import { ModelPicker } from './ModelPicker';
import type { Agent, Task, Snapshot, MemoryRecord } from '../shared/types';

const NAV = [{url:'/office',label:'Офис',icon:'office'},{url:'/tasks',label:'Задачи',icon:'tasks'},{url:'/agents',label:'Агенты',icon:'agents'},{url:'/history',label:'История',icon:'history'},{url:'/settings',label:'Настройки',icon:'settings'}];
const STATUS:Record<string,{label:string;kind:string;icon:string}> = {
 ready:{label:'Готов к задаче',kind:'idle',icon:'coffee'},idle:{label:'Свободен',kind:'idle',icon:'coffee'},requires_setup:{label:'Требуется настройка',kind:'setup',icon:'plug'}, draft:{label:'Черновик',kind:'idle',icon:'edit'},scheduled:{label:'Запланировано',kind:'idle',icon:'clock'},queued:{label:'В очереди',kind:'run',icon:'clock'},running:{label:'Выполняется',kind:'run',icon:'run'},waiting_for_input:{label:'Нужен ответ',kind:'wait',icon:'alert'},waiting_for_approval:{label:'Нужно решение',kind:'wait',icon:'alert'},pause_requested:{label:'Ожидает паузы',kind:'wait',icon:'pause'},paused:{label:'На паузе',kind:'pause',icon:'pause'},retry_scheduled:{label:'Ожидает повтора',kind:'wait',icon:'clock'},ready_for_review:{label:'Готов к проверке',kind:'done',icon:'check'},completed:{label:'Завершено',kind:'done',icon:'check'},failed:{label:'Ошибка',kind:'err',icon:'warn'},cancel_requested:{label:'Ожидает отмены',kind:'wait',icon:'stop'},cancelled:{label:'Отменено',kind:'pause',icon:'stop'},archived:{label:'В архиве',kind:'pause',icon:'history'}
};
const officeZones=(agents:Agent[])=>Array.from({length:Math.max(1,Math.ceil(agents.length/4))},(_,index)=>({label:`Зона ${index+1}`,agents:agents.slice(index*4,index*4+4)}));
const TABS = [['overview','Обзор'],['chat','Чат'],['memory','Память'],['instructions','Инструкции'],['tools','Инструменты и доступ'],['activity','Активность']];
let displayTimezone: string|undefined;
const date=(value?:string)=>{if(!value)return '—';try{return new Date(value).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:displayTimezone});}catch{return new Date(value).toLocaleString('ru-RU');}};
const dayKey=(value:string|Date)=>{try{return new Date(value).toLocaleDateString('en-CA',{timeZone:displayTimezone});}catch{return new Date(value).toDateString();}};
const modelReady=(snapshot:Snapshot,agent?:Agent)=>!!snapshot.settings.credentialsConfigured&&!!(agent?.model||snapshot.settings.model)&&snapshot.settings.checkedModels?.includes(agent?.model||snapshot.settings.model);
function localDateToUtc(value:string,timeZone:string){const parts=value.split(/[-T:]/).map(Number);const desired=Date.UTC(parts[0],parts[1]-1,parts[2],parts[3],parts[4]);let utc=desired;for(let i=0;i<3;i++){const f=new Intl.DateTimeFormat('en-CA',{timeZone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(utc));const part=(type:string)=>Number(f.find(x=>x.type===type)?.value);const actual=Date.UTC(part('year'),part('month')-1,part('day'),part('hour'),part('minute'));utc+=desired-actual;}return new Date(utc).toISOString();}

function Icon({name,size=20}:{name:string;size?:number}){return <svg width={size} height={size} className="icon" aria-hidden="true"><use href={`/design/icons.svg#i-${name}`}/></svg>}
function Status({value}:{value:string}){const s=STATUS[value]||{label:value||'Требуется настройка',kind:'setup',icon:'plug'};return <span className={`chip ${s.kind}`}><Icon name={s.icon} size={15}/>{s.label}</span>}
function Avatar({agent,size=40}:{agent:Agent;size?:number}){return <span className="avatar" style={{background:agent.color||'#b5abff',width:size,height:size}}>{agent.avatar?.length<=3?agent.avatar:agent.name.slice(0,1)}</span>}
function Empty({icon='office',title,children}:{icon?:string;title:string;children?:ReactNode}){return <div className="empty"><span className="empty-icon"><Icon name={icon} size={30}/></span><h3>{title}</h3><div className="muted">{children}</div></div>}
function FormField({label,hint,children}:{label:string;hint?:string;children:ReactNode}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function FormMessage({error}:{error?:string}){return error?<p className="form-error" role="alert"><Icon name="warn"/>{error}</p>:null}

export function OrvoApp({path=[]}:{path?:string[]}){
 const router=useRouter();const [state,setState]=useState<Snapshot|null>(null);const [loading,setLoading]=useState(true);const [connection,setConnection]=useState('connecting');const [lastSync,setLastSync]=useState<Date|null>(null);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [notice,setNotice]=useState('');const [notifications,setNotifications]=useState(false);const [selected,setSelected]=useState<string|null>(null);const [tab,setTab]=useState('overview');const [mode,setMode]=useState<'office'|'list'>('office');const [zone,setZone]=useState(0);const [zoom,setZoom]=useState(1);const [showCreateAgent,setShowCreateAgent]=useState(false);const pending=useRef(false);const retryCommand=useRef<{fingerprint:string;id:string}|null>(null);
 const page=path[0]||'office';const taskId=page==='tasks'&&path[1]&&path[1]!=='new'?path[1]:null;const newTask=page==='tasks'&&path[1]==='new';
 useEffect(()=>{if(window.matchMedia('(max-width: 720px)').matches)setMode('list');if(page==='agents'&&path[1])setSelected(path[1]);else setSelected(null);setTab(new URLSearchParams(window.location.search).get('tab')||'overview');},[page,path.join('/')]);
 const load=useCallback(async()=>{const response=await fetch('/api/state',{cache:'no-store'});if(response.status===401){router.replace('/login');throw new Error('Войдите в рабочее пространство');}const data=await response.json();if(!response.ok)throw new Error(data.error?.message||'Не удалось синхронизировать данные');setState(data);setLastSync(new Date());setConnection('connected');setLoading(false);return data as Snapshot;},[router]);
 const activeTaskPolling=state?.tasks.some((task:Task)=>task.status==='queued'||task.status==='running')??false;
 useEffect(()=>{let stopped=false;let timer:ReturnType<typeof setTimeout>;let failures=0;const sync=async()=>{try{await load();failures=0;}catch(e){if(!stopped){setConnection('offline');setError((e as Error).message);setLoading(false);}failures++;}if(!stopped)timer=setTimeout(sync,failures?Math.min(30000,4000*2**failures):activeTaskPolling?900:4000);};sync();const onFocus=()=>{if(!document.hidden)load().catch(()=>setConnection('offline'));};window.addEventListener('focus',onFocus);return()=>{stopped=true;clearTimeout(timer);window.removeEventListener('focus',onFocus);};},[load,activeTaskPolling]);
 useEffect(()=>{if(notice){const id=setTimeout(()=>setNotice(''),4500);return()=>clearTimeout(id);}},[notice]);
 const command=async(type:string,payload:Record<string,unknown>={})=>{if(pending.current)throw new Error('Дождитесь сохранения текущего действия');pending.current=true;setBusy(true);setError('');try{const fingerprint=JSON.stringify({type,payload});const requestId=retryCommand.current?.fingerprint===fingerprint?retryCommand.current.id:crypto.randomUUID();retryCommand.current={fingerprint,id:requestId};const response=await fetch('/api/command',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type,payload,requestId})});if(response.status===401){router.replace('/login');throw new Error('Сессия завершена. Войдите снова.');}const data=await response.json();if(!response.ok){retryCommand.current=null;throw new Error(data.error?.message||'Не удалось выполнить действие');}retryCommand.current=null;await load().catch(()=>setConnection('offline'));return data.result??data;}catch(e){setError((e as Error).message);throw e;}finally{pending.current=false;setBusy(false);}};
 const action=(type:string,payload:Record<string,unknown>={},message='Сохранено')=>command(type,payload).then(()=>setNotice(message)).catch(()=>{});
 const openAgent=(id:string)=>{setSelected(id);setTab('overview');};
 if(!state)return <main className="boot"><div className="brand"><span className="brand-mark">◇</span>orvo</div>{loading?<><span className="spinner"/>Подключаем рабочее пространство…</>:<><FormMessage error={error}/><button className="button" onClick={()=>load().catch(e=>setError(e.message))}>Повторить подключение</button></>}</main>;
 displayTimezone=state.settings.timezone||undefined;
 const agents=state.agents.filter(a=>!a.archived);const zones=officeZones(agents);const activeZone=Math.min(zone,zones.length-1);const agent=state.agents.find(a=>a.id===selected);const tasks=state.tasks;const running=tasks.filter(t=>['running','pause_requested','cancel_requested'].includes(t.status));const decisions=state.approvals.filter(a=>a.status==='pending');const waiting=tasks.filter(t=>['waiting_for_input','waiting_for_approval'].includes(t.status));const completed=tasks.filter(t=>t.status==='completed'&&dayKey(t.updatedAt)===dayKey(new Date()));const unread=state.notifications.filter(n=>!n.readAt&&!n.read);const theme=state.settings.theme||'dark';const currentTask=tasks.find(t=>t.id===taskId);const configured=modelReady(state);const title=page==='office'?'Ваш офис':page==='agents'?'Агенты':page==='history'?'История':page==='settings'?'Настройки':newTask?'Новая задача':currentTask?.title||'Задачи';
 const agentStatus=(a:Agent)=>a.archived?'archived':currentAgentTask(tasks,a.id)?.status||(a.status||(!modelReady(state,a)?'requires_setup':'idle'));
 return <div className={`orvo o ${theme==='light'?'light':''}`} data-theme={theme}>
 <aside className="sidebar"><a href="/office" className="brand"><span className="brand-mark"><Icon name="office" size={24}/></span>orvo</a><nav aria-label="Основная навигация">{NAV.map(n=><a key={n.url} href={n.url} className={page===n.url.slice(1)?'active':''} aria-current={page===n.url.slice(1)?'page':undefined}><Icon name={n.icon}/>{n.label}{n.url==='/agents'&&<span className="count">{agents.length}</span>}{n.url==='/tasks'&&waiting.length>0&&<span className="count wait">{waiting.length}</span>}</a>)}</nav>
 <div className="sidebar-bottom"><div className="budget-card"><div className="muted"><Icon name="coins" size={17}/>Использование</div><strong className="display">{state.usage.reduce((v,u)=>v+(u.tokens||u.totalTokens||0),0).toLocaleString('ru-RU')} <span>токенов</span></strong><div className="subtle">{configured?'Модель настроена':'Подключите модель для работы'}</div><a href="/settings" className="text-link">Настройки и лимиты <span>↗</span></a></div><div className="segmented"><button aria-pressed={theme==='dark'} onClick={()=>action('settings.save',{theme:'dark'})}><Icon name="moon" size={16}/>Тёмная</button><button aria-pressed={theme==='light'} onClick={()=>action('settings.save',{theme:'light'})}><Icon name="sun" size={16}/>Светлая</button></div><a href="/settings" className="owner"><span className="avatar owner-avatar">{(state.settings.name||state.workspace.name||'О').slice(0,1)}</span><span><strong>{state.settings.name||state.workspace.name||'Ваше пространство'}</strong><small>Личный офис · владелец</small></span><Icon name="settings" size={17}/></a></div></aside>
 <div className="workspace"><header className="topbar"><div className="breadcrumb">Рабочее пространство<span>/</span><strong>{page==='office'?'Офис':NAV.find(n=>n.url===`/${page}`)?.label||'Orvo'}</strong></div><div className="topbar-actions"><span className={`connection ${connection}`} title={lastSync?`Синхронизация: ${lastSync.toLocaleTimeString('ru-RU')}`:''}><i/>{connection==='connected'?'Синхронизировано':connection==='offline'?'Нет соединения':'Подключение'}{lastSync&&<small>{lastSync.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</small>}</span><button className="icon-button notification-button" aria-label={`Уведомления: ${unread.length} непрочитанных`} aria-expanded={notifications} onClick={()=>setNotifications(!notifications)}><Icon name="bell"/>{unread.length>0&&<i/>}</button></div></header>
 {notifications&&<section className="notifications card" aria-label="Уведомления"><div className="section-heading"><h3>Уведомления</h3><button className="text-link" onClick={()=>action('notifications.read',{})}>Прочитать все</button><button className="icon-button" aria-label="Закрыть уведомления" onClick={()=>setNotifications(false)}><Icon name="x"/></button></div>{state.notifications.length===0?<p className="muted">Новых событий пока нет.</p>:state.notifications.slice().reverse().map(n=><button className={`notification-item ${!n.readAt&&!n.read?'unread':''}`} key={n.id} onClick={()=>{action('notifications.read',{id:n.id});if(n.taskId)router.push(`/tasks/${n.taskId}`);}}><Icon name={(n.kind||n.type)?.includes('error')?'warn':'bell'}/><span><strong>{n.title||n.message||'Обновление задачи'}</strong>{n.body&&<small>{n.body}</small>}<small>{date(n.createdAt)}</small></span></button>)}</section>}
 <main className={`content ${newTask?'new-task-page':''}`}><div className="page-heading"><div><p className="eyebrow">ORVO · ЛИЧНОЕ ПРОСТРАНСТВО</p><h1>{title}</h1><p className="muted">{page==='office'?'Ваши агенты и поручения в одном пространстве.':page==='agents'?'Создавайте своих агентов с отдельными инструкциями и памятью.':page==='history'?'Сохранённые результаты и проверяемые события.':page==='settings'?'Ваш профиль, модель и границы работы команды.':newTask?'Расскажите, что нужно сделать. Исполнителя можно выбрать автоматически.':'От первого поручения до принятого результата.'}</p></div>{!newTask&&page!=='settings'&&<a href="/tasks/new" className="button primary new-task-cta"><Icon name="plus" size={18}/>Новая задача</a>}</div>
 {state.settings.provider==='test'&&<div className="test-banner"><Icon name="warn" size={18}/><span><strong>Тестовый режим.</strong> Ответы создаёт управляемый тестовый провайдер. Это не обращение к ИИ-модели.</span></div>}
 {error&&<div className="error-banner" role="alert"><Icon name="warn"/><span>{error}</span><button className="icon-button" aria-label="Скрыть ошибку" onClick={()=>setError('')}><Icon name="x"/></button></div>}
 {connection==='offline'&&<div className="warning-banner"><Icon name="plug"/><span>Связь прервана. Последние данные: {lastSync?.toLocaleTimeString('ru-RU')||'не получены'}. Выполнение на сервере не зависит от вкладки.</span><button className="text-link" onClick={()=>load().catch(()=>{})}>Переподключиться</button></div>}
 {page==='office'&&<><div className="summary-grid"><Summary icon="run" value={running.length} label="Выполняется" kind="run"/><Summary icon="alert" value={waiting.length} label="Требуется решение" kind="wait"/><Summary icon="check" value={completed.length} label="Завершено сегодня" kind="done"/></div><Approvals snapshot={state} command={command}/>
 {!configured&&<div className="setup-banner"><div className="setup-icon"><Icon name="plug"/></div><div><strong>Офис готов знакомиться с задачами</strong><p>Подключите модель в настройках. Создание профилей не запускает обращения к модели.</p></div><a href="/settings" className="button secondary">Настроить модель <span>↗</span></a></div>}
 <section className="office-section"><div className="section-heading"><div><h2>Команда в офисе <span className="quiet-count">{agents.length}</span></h2><p className="subtle">Нажмите на сотрудника, чтобы открыть его пространство</p></div><div className="segmented mode-switch"><button aria-pressed={mode==='office'} onClick={()=>setMode('office')}><Icon name="office" size={17}/>Офис</button><button aria-pressed={mode==='list'} onClick={()=>setMode('list')}><Icon name="agents" size={17}/>Список</button></div></div>
 {mode==='office'?<><div className="zone-tabs" role="tablist" aria-label="Зоны офиса">{zones.map((z,i)=><button key={z.label} role="tab" aria-selected={activeZone===i} onClick={()=>setZone(i)}><span className="zone-index">0{i+1}</span>{z.label}<span className="count">{z.agents.length}</span></button>)}</div><div className="office-viewport"><div className="office-scene" style={{width:`${100*zoom}%`}}><img className="office-background" src="/design/office-background.svg" alt="Пиксельный офис Orvo со столами, растениями и переговорной"/><span className="room-label">{zones[activeZone].label}</span>{Array.from({length:4},(_,i)=>i).filter(i=>!zones[activeZone].agents[i]).map(i=><img key={`empty-${i}`} className="office-workstation" src={`/design/empty-workstation-${((activeZone*4+i)%6)+1}.svg`} alt="" aria-hidden="true" style={{left:`${i%2===0?22:49}%`,top:`${i<2?23:58}%`}}/>)}{zones[activeZone].agents.map((a,i)=><button className={`office-agent ${agentStatus(a)==='waiting_for_approval'?'needs-decision':''}`} key={a.id} style={{left:`${i%2===0?22:49}%`,top:`${i<2?23:58}%`}} onClick={()=>openAgent(a.id)} aria-label={`Открыть ${a.name}, ${a.role}, ${STATUS[agentStatus(a)]?.label||agentStatus(a)}`}>{agentStatus(a)==='running'?<><img className="workstation-motion" src={`/design/workstation-working-${(agents.indexOf(a)%6)+1}.svg`} alt=""/><img className="workstation-still" src={`/design/workstation-${(agents.indexOf(a)%6)+1}.svg`} alt=""/></>:<img src={`/design/workstation-${(agents.indexOf(a)%6)+1}.svg`} alt=""/>}<span className="agent-label"><span className="agent-label-name"><i style={{background:a.color}}/>{a.name}<Icon name="expand" size={12}/></span><span className="agent-label-role">{a.role}</span>{agentStatus(a)==='running'&&<span className="office-work-indicator"><Icon name="run" size={11}/>Работает</span>}<Status value={agentStatus(a)}/></span></button>)}</div></div>{agents.length===0&&<div className="office-empty-caption"><p>Офис готов. Создайте своего первого агента.</p><button className="button primary" onClick={()=>setShowCreateAgent(true)}><Icon name="plus" size={16}/>Создать агента</button></div>}<div className="office-footer"><span><i className="legend-dot run"/>В работе <i className="legend-dot wait"/>Ждёт решения <i className="legend-dot setup"/>Настройка</span><div><button className="icon-button" aria-label="Уменьшить офис" onClick={()=>setZoom(Math.max(1,zoom-.2))}>−</button><span className="mono">{Math.round(zoom*100)}%</span><button className="icon-button" aria-label="Увеличить офис" onClick={()=>setZoom(Math.min(1.8,zoom+.2))}>+</button></div></div></>:<AgentList agents={agents} status={agentStatus} open={openAgent}/>}
 </section><div className="server-note"><Icon name="server" size={16}/>{running.length?`${running.length} выполняются на сервере`:'Нет выполняемых заданий'}{tasks.filter(t=>t.status==='queued').length>0?` · в очереди: ${tasks.filter(t=>t.status==='queued').length}`:''} · закрытие вкладки не отменяет задачу.</div></>}
 {page==='agents'&&<><div className="section-heading"><div className="inline"><span className="chip idle">{agents.length} активных</span><span className="subtle">{state.agents.filter(a=>a.archived).length} в архиве</span></div><div className="inline"><button className="button secondary" onClick={()=>setShowCreateAgent(true)}><Icon name="plus" size={17}/>Добавить агента</button></div></div><AgentCatalog agents={state.agents} status={agentStatus} open={openAgent}/></>}
 {page==='tasks'&&(newTask?<TaskForm snapshot={state} command={command} onDone={id=>router.push(`/tasks/${id}`)}/>:currentTask?<TaskDetails task={currentTask} snapshot={state} command={command} openAgent={openAgent}/>:<TaskList snapshot={state} openAgent={openAgent}/>)}
 {page==='history'&&<History snapshot={state}/>}
 {page==='settings'&&<Settings snapshot={state} command={command}/>}
 </main><footer className="page-footer"><span>Orvo — пространство для осмысленной работы</span><span>Приватный офис <Icon name="office" size={14}/></span></footer></div>
 <nav className="mobile-nav" aria-label="Мобильная навигация">{NAV.map(n=><a key={n.url} href={n.url} className={page===n.url.slice(1)?'active':''}><Icon name={n.icon} size={21}/><span>{n.label}</span></a>)}</nav>
 {agent&&<AgentPanel agent={agent} snapshot={state} status={agentStatus(agent)} tab={tab} setTab={value=>{setTab(value);if(page==='agents'&&path[1])history.replaceState(null,'',`/agents/${agent.id}?tab=${value}`);}} command={command} close={()=>{setSelected(null);if(page==='agents'&&path[1])router.push('/agents');}}/>}
 {showCreateAgent&&<Dialog title="Новый агент" close={()=>setShowCreateAgent(false)}><CreateAgent command={command} done={()=>setShowCreateAgent(false)}/></Dialog>}
 {notice&&<div className="toast" role="status"><Icon name="check"/>{notice}</div>}
 </div>;
}
function Summary({icon,value,label,kind}:{icon:string;value:number;label:string;kind:string}){return <div className={`summary-card ${kind}`}><span className="summary-icon"><Icon name={icon}/></span><span><strong className="display">{value}</strong><span>{label}</span></span><span className="summary-line"/></div>}
function AgentList({agents,status,open}:{agents:Agent[];status:(a:Agent)=>string;open:(id:string)=>void}){return <div className="agent-list">{agents.map(a=><button className="agent-list-row" key={a.id} onClick={()=>open(a.id)}><Avatar agent={a}/><span className="agent-name"><strong>{a.name}</strong><small>{a.role}</small></span><Status value={status(a)}/><span className="row-arrow">↗</span></button>)}{agents.length===0&&<Empty title="В офисе пока никого" icon="agents">Создайте своего первого агента во вкладке «Агенты».</Empty>}</div>}
function AgentCatalog({agents,status,open}:{agents:Agent[];status:(a:Agent)=>string;open:(id:string)=>void}){const [search,setSearch]=useState('');const [archived,setArchived]=useState(false);const filtered=agents.filter(a=>a.archived===archived&&`${a.name} ${a.role}`.toLowerCase().includes(search.toLowerCase()));return <><div className="filters"><label className="search-field"><Icon name="agents" size={18}/><input aria-label="Найти агента" placeholder="Имя или роль…" value={search} onChange={e=>setSearch(e.target.value)}/></label><label className="checkbox"><input type="checkbox" checked={archived} onChange={e=>setArchived(e.target.checked)}/>Показать архив</label></div><div className="agent-catalog">{filtered.map(a=><button key={a.id} className="agent-card card" onClick={()=>open(a.id)}><div className="agent-card-top"><Avatar agent={a} size={44}/><span className="row-arrow">↗</span></div><h3>{a.name}</h3><p className="agent-role">{a.role}</p><p className="muted">{a.description}</p><div className="agent-card-bottom"><Status value={status(a)}/><span className="subtle mono">v{a.instructionVersion}</span></div></button>)}</div>{!filtered.length&&<Empty title="Агенты не найдены" icon="agents">Измените поиск или переключитесь на активные профили.</Empty>}</>}
function Approvals({snapshot,command}:{snapshot:Snapshot;command:Command}){const pending=snapshot.approvals.filter(a=>a.status==='pending');if(!pending.length)return null;return <section className="approval-banner"><div className="approval-heading"><span className="approval-icon"><Icon name="alert"/></span><div><h3>{pending.length===1?'Команде нужно ваше решение':`${pending.length} действий ждут решения`}</h3><p>Проверьте конкретное действие перед подтверждением.</p></div></div>{pending.map(a=><div className="approval-item" key={a.id}><div><strong>{a.title||a.description||a.action||'Сохранить правило в памяти'}</strong><p className="muted">{a.tool||a.toolName||'Внутренний инструмент'} · {snapshot.agents.find(g=>g.id===a.agentId)?.name||'Агент'}</p>{(a.params||a.payload)&&<pre className="approval-payload">{JSON.stringify(a.params||a.payload,null,2)}</pre>}<small>Запрос от {date(a.createdAt)}{a.expiresAt&&` · действует до ${date(a.expiresAt)}`}</small></div><div className="inline"><a href={`/tasks/${a.taskId}`} className="button quiet">К задаче</a><CommandButton command={command} type="approval.decide" payload={{id:a.id,version:a.version,decision:'reject'}} className="button secondary">Отклонить</CommandButton><CommandButton command={command} type="approval.decide" payload={{id:a.id,version:a.version,decision:'approve'}} className="button approve"><Icon name="check" size={16}/>Подтвердить</CommandButton></div></div>)}</section>}
type Command=(type:string,payload?:Record<string,unknown>)=>Promise<any>;
function CommandButton({command,type,payload,children,className='button secondary'}:{command:Command;type:string;payload:Record<string,unknown>;children:ReactNode;className?:string}){const [busy,setBusy]=useState(false);return <button className={className} disabled={busy} onClick={async()=>{setBusy(true);try{await command(type,payload);}catch{}finally{setBusy(false);}}}>{busy?<span className="spinner small"/>:null}{children}</button>}
function Dialog({title,children,close}:{title:string;children:ReactNode;close:()=>void}){const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const previous=document.activeElement as HTMLElement;ref.current?.focus();const listener=(e:KeyboardEvent)=>{if(e.key==='Escape')close();if(e.key==='Tab'&&ref.current){const list=ref.current.querySelectorAll<HTMLElement>('button,a[href],input,textarea,select,[tabindex="0"]');const first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};document.addEventListener('keydown',listener);const old=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',listener);document.body.style.overflow=old;previous?.focus();};},[]);return <div className="dialog-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close();}}><div className="dialog" role="dialog" aria-modal="true" aria-label={title} tabIndex={-1} ref={ref}><div className="section-heading"><h2>{title}</h2><button className="icon-button" aria-label="Закрыть" onClick={close}><Icon name="x"/></button></div>{children}</div></div>}
function CreateAgent({command,done}:{command:Command;done:()=>void}){const [error,setError]=useState('');const [busy,setBusy]=useState(false);return <form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');const f=new FormData(e.currentTarget);try{await command('agents.create',Object.fromEntries(f));done();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}}><FormField label="Имя"><input name="name" required maxLength={80}/></FormField><FormField label="Роль"><input name="role" required maxLength={120}/></FormField><FormField label="Обязанности"><textarea name="description" required rows={3}/></FormField><FormField label="Инструкции"><textarea name="instructions" required rows={5}/></FormField><FormMessage error={error}/><button className="button primary" disabled={busy}>Создать профиль</button></form>}
function AgentPanel({agent,snapshot,status,tab,setTab,command,close}:{agent:Agent;snapshot:Snapshot;status:string;tab:string;setTab:(v:string)=>void;command:Command;close:()=>void}){
 const ref=useRef<HTMLElement>(null);const tasks=snapshot.tasks.filter(t=>t.agentId===agent.id);const active=currentAgentTask(tasks,agent.id);const [error,setError]=useState('');const [saving,setSaving]=useState(false);
 useEffect(()=>{const previous=document.activeElement as HTMLElement;ref.current?.focus();const old=document.body.style.overflow;document.body.style.overflow='hidden';const listener=(e:KeyboardEvent)=>{if(e.key==='Escape')close();if(e.key==='Tab'&&ref.current){const els=ref.current.querySelectorAll<HTMLElement>('button,a[href],input,textarea,select,[tabindex="0"]');const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};document.addEventListener('keydown',listener);return()=>{document.body.style.overflow=old;document.removeEventListener('keydown',listener);previous?.focus();};},[]);
 const saveProfile=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setSaving(true);setError('');const f=new FormData(e.currentTarget);try{await command('agents.update',{id:agent.id,version:agent.version,name:f.get('name'),role:f.get('role'),description:f.get('description'),color:f.get('color'),avatar:f.get('avatar'),model:f.get('model')||null});}catch(e){setError((e as Error).message);}finally{setSaving(false);}};
 return <div className="panel-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close();}}><aside ref={ref} className="agent-panel" role="dialog" aria-modal="true" aria-label={`Панель агента ${agent.name}`} tabIndex={-1}>
 <header className="panel-header"><Avatar agent={agent} size={48}/><div><h2>{agent.name}</h2><p>{agent.role}</p></div><button className="icon-button" aria-label="Закрыть панель агента" onClick={close}><Icon name="x"/></button></header><div className="panel-status"><Status value={status}/><span className="subtle mono">{agent.roleKey}</span></div>
 <div className="panel-tabs" role="tablist" aria-label="Разделы агента">{TABS.map(([key,label])=><button role="tab" aria-selected={tab===key} aria-controls={`panel-${key}`} id={`tab-${key}`} key={key} onClick={()=>setTab(key)}>{label}</button>)}</div>
 <div className="panel-body" role="tabpanel" id={`panel-${tab}`} aria-labelledby={`tab-${tab}`}>
 {tab==='overview'&&<><section className="panel-section"><h3>Сейчас в работе</h3>{active?<><a className="current-task" href={`/tasks/${active.id}`}><strong>{active.title}</strong><Icon name="expand" size={16}/></a><Status value={active.status}/><p className="muted">{active.currentStep||'Текущий этап появится после запуска.'}</p><p className="subtle">Обновлено {date(active.updatedAt)}</p></>:<div className="idle-block"><span className="idle-illustration"><Icon name={status==='requires_setup'?'plug':'coffee'} size={28}/></span><strong>{status==='requires_setup'?'Требуется настройка модели':'Готов к следующей задаче'}</strong><p>{status==='requires_setup'?'Настройте общую модель или задайте модель для этого профиля.':'Поручите работу: инструкции и память помогут сохранить контекст.'}</p><a className="button primary" href={`/tasks/new?agent=${agent.id}`}><Icon name="plus" size={17}/>Поставить задачу</a></div>}</section>
 <section className="panel-section"><div className="section-heading"><h3>Профиль агента</h3><span className="subtle">v{agent.version}</span></div><form onSubmit={saveProfile}><div className="form-grid"><FormField label="Имя"><input name="name" defaultValue={agent.name} required maxLength={80}/></FormField><FormField label="Цвет"><input type="color" name="color" defaultValue={agent.color||'#9f91ff'}/></FormField></div><FormField label="Аватар / инициалы"><input name="avatar" defaultValue={agent.avatar?.length<=3?agent.avatar:agent.name.slice(0,1)} maxLength={3} required/></FormField><FormField label="Роль"><input name="role" defaultValue={agent.role} required/></FormField><FormField label="Обязанности"><textarea name="description" defaultValue={agent.description} rows={4}/></FormField><ModelPicker defaultValue={agent.model||''} inherit provider={snapshot.settings.provider} testProvider={snapshot.settings.provider==='test'}/><FormMessage error={error}/><button className="button secondary" disabled={saving}>Сохранить профиль</button></form><div className="saved-model-check"><CommandButton command={command} type="settings.checkModel" payload={{agentId:agent.id}}><Icon name="plug" size={15}/>Проверить сохранённую модель</CommandButton><p className="subtle">Проверка может расходовать токены подключённой модели.</p></div></section>
 <section className="panel-section"><h3>Задачи агента <span className="quiet-count">{tasks.length}</span></h3>{tasks.length?tasks.slice(0,6).map(t=><a className="mini-task" href={`/tasks/${t.id}`} key={t.id}><span>{t.title}</span><Status value={t.status}/></a>):<p className="muted">История поручений пока пуста.</p>}</section><section className="panel-section"><h3>Управление профилем</h3><p className="subtle">Архивация сохраняет память, историю и результаты. Активные задачи требуют отдельного решения.</p><CommandButton command={command} type={agent.archived?'agents.update':'agents.archive'} payload={agent.archived?{id:agent.id,version:agent.version,archived:false}:{id:agent.id}} className="button secondary">{agent.archived?'Вернуть из архива':'Архивировать агента'}</CommandButton></section></>}
 {tab==='chat'&&<Chat agent={agent} snapshot={snapshot} command={command}/>}
 {tab==='memory'&&<Memory agent={agent} snapshot={snapshot} command={command}/>}
 {tab==='instructions'&&<Instructions agent={agent} snapshot={snapshot} command={command}/>}
 {tab==='tools'&&<Tools agent={agent} snapshot={snapshot} command={command}/>}
 {tab==='activity'&&<Activity events={snapshot.events.filter(e=>e.agentId===agent.id||tasks.some(t=>t.id===e.taskId)||e.agentId===agent.id)}/>}
 </div><footer className="panel-footer"><Icon name="server" size={16}/><span>Состояние хранится на сервере</span><a className="text-link" href={`/agents/${agent.id}?tab=${tab}`}>Полная карточка ↗</a></footer></aside></div>;
}
function Chat({agent,snapshot,command}:{agent:Agent;snapshot:Snapshot;command:Command}){
 const [text,setText]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [rule,setRule]=useState<string|null>(null);const [ruleScope,setRuleScope]=useState('agent');const [project,setProject]=useState('');const [task,setTask]=useState('');const messages=snapshot.messages.filter(m=>m.agentId===agent.id&&(!task? !m.taskId:m.taskId===task));
 const submit=async(e:FormEvent)=>{e.preventDefault();if(!text.trim())return;setBusy(true);setError('');try{await command('chat.send',{agentId:agent.id,taskId:task||undefined,text:text.trim()});setText('');}catch(e){setError((e as Error).message);}finally{setBusy(false);}};
 return <div className="chat-layout"><div className="panel-section"><FormField label="Контекст разговора"><select value={task} onChange={e=>setTask(e.target.value)}><option value="">Общий чат агента</option>{snapshot.tasks.filter(t=>t.agentId===agent.id).map(t=><option key={t.id} value={t.id}>{t.title}</option>)}</select></FormField><p className="subtle">Сообщение сохраняется в истории. Чтобы получить результат от модели, создайте и запустите задачу.</p></div><div className="chat-messages">{messages.length?messages.map(m=><article className={`message ${m.role==='user'?'mine':'theirs'}`} key={m.id}><div className="message-author">{m.role==='user'?'Вы':m.role==='system'?'Система':agent.name}<time>{date(m.createdAt)}</time></div><p>{m.text||m.content}</p><button className="rule-button" onClick={()=>setRule(m.text||m.content)}><Icon name="bookmark" size={14}/>Запомнить как правило</button></article>):<Empty icon="wave" title="Начните с контекста">Расскажите о задаче или сохраните важную мысль. Общий чат сам по себе не запускает работу.</Empty>}</div>
 {rule!==null&&<div className="rule-editor card"><h3>Сохранить правило</h3><FormField label="Текст"><textarea value={rule} onChange={e=>setRule(e.target.value)} rows={3}/></FormField><FormField label="Область памяти"><select value={ruleScope} onChange={e=>setRuleScope(e.target.value)}><option value="agent">Только {agent.name}</option><option value="workspace">Вся команда</option><option value="project">Проект</option></select></FormField>{ruleScope==='project'&&<ProjectPicker snapshot={snapshot} command={command} value={project} onChange={setProject} required/>}<RelatedMemories text={rule} memories={snapshot.memories.filter(m=>m.scope==='workspace'||m.agentId===agent.id||m.projectId===project)}/><div className="inline"><button className="button primary" onClick={async()=>{try{await command('memory.save',{agentId:ruleScope==='agent'?agent.id:undefined,projectId:ruleScope==='project'?project:undefined,scope:ruleScope,text:rule,type:'rule',source:'chat'});setRule(null);}catch(e){setError((e as Error).message);}}}>Сохранить правило</button><button className="button secondary" onClick={()=>setRule(null)}>Отмена</button></div></div>}
 <form className="chat-composer" onSubmit={submit}><FormMessage error={error}/><label className="sr-only" htmlFor="chat-message">Сообщение агенту</label><textarea id="chat-message" value={text} onChange={e=>setText(e.target.value)} placeholder={`Сообщение для ${agent.name}…`} rows={3} maxLength={12000}/><div className="composer-actions"><a className="text-link" href={`/tasks/new?agent=${agent.id}&context=${encodeURIComponent(text.slice(0,1500))}`}><Icon name="plus" size={16}/>Предложить задачу</a><button className="button primary" disabled={busy||!text.trim()}><Icon name="send" size={17}/>Сохранить</button></div></form></div>;
}
function Memory({agent,snapshot,command}:{agent:Agent;snapshot:Snapshot;command:Command}){
 const [editing,setEditing]=useState<MemoryRecord|null>(null);const [text,setText]=useState('');const [scope,setScope]=useState('agent');const [type,setType]=useState('rule');const [project,setProject]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);const memories=snapshot.memories.filter(m=>m.active!==false&&(m.scope==='workspace'||m.agentId===agent.id||m.scope==='project'));
 const edit=(m:MemoryRecord)=>{setEditing(m);setText(m.text);setScope(m.scope);setType(m.type);setProject(m.projectId||'');};
 const save=async(e:FormEvent)=>{e.preventDefault();setError('');setBusy(true);try{await command('memory.save',{id:editing?.id,version:editing?.version,agentId:scope==='agent'?agent.id:undefined,projectId:scope==='project'?project:undefined,scope,type,text});setText('');setEditing(null);}catch(e){setError((e as Error).message);}finally{setBusy(false);}};
 return <><section className="panel-section"><h3>Память, которую можно проверить</h3><p className="muted">Сохранённые правила и факты используются в подходящем контексте. Это не дообучение модели.</p><div className="memory-list">{memories.map(m=><article className="memory-card" key={m.id}><div className="inline"><span className="chip idle">{m.scope==='agent'?'Агент':m.scope==='project'?`Проект: ${m.projectId}`:'Вся команда'}</span><small className="subtle">{m.type==='rule'?'Правило':m.type==='fact'?'Факт':'Предпочтение'} · v{m.version}</small></div><p>{m.text}</p><div className="memory-meta"><small>Источник: {m.source||'владелец'}</small><div className="inline"><button className="text-link" onClick={()=>edit(m)}>Изменить</button><CommandButton command={command} type="memory.delete" payload={{id:m.id,version:m.version}} className="text-link danger">Удалить</CommandButton></div></div></article>)}{!memories.length&&<p className="muted">Пока нет сохранённых записей.</p>}</div></section><section className="panel-section"><h3>{editing?'Изменить запись':'Новая запись'}</h3><form onSubmit={save}><div className="form-grid"><FormField label="Область"><select value={scope} onChange={e=>setScope(e.target.value)}><option value="agent">Только этот агент</option><option value="workspace">Вся команда</option><option value="project">Проект</option></select></FormField><FormField label="Тип"><select value={type} onChange={e=>setType(e.target.value)}><option value="rule">Правило</option><option value="fact">Факт</option><option value="preference">Предпочтение</option></select></FormField></div>{scope==='project'&&<ProjectPicker snapshot={snapshot} command={command} value={project} onChange={setProject} required/>}<FormField label="Текст записи"><textarea required value={text} onChange={e=>setText(e.target.value)} rows={4} maxLength={12000}/></FormField><RelatedMemories text={text} memories={memories.filter(m=>m.id!==editing?.id)}/><FormMessage error={error}/><div className="inline"><button className="button primary" disabled={busy}>{editing?'Сохранить изменения':'Добавить запись'}</button>{editing&&<button type="button" className="button secondary" onClick={()=>{setEditing(null);setText('');}}>Отмена</button>}</div></form></section></>;
}
function Instructions({agent,snapshot,command}:{agent:Agent;snapshot:Snapshot;command:Command}){const [text,setText]=useState(agent.instructions);const [error,setError]=useState('');const [saved,setSaved]=useState(false);const [busy,setBusy]=useState(false);return <section className="panel-section"><div className="section-heading"><h3>Собственные инструкции</h3><span className="chip idle mono">Версия {agent.instructionVersion}</span></div><p className="muted">Определяют обязанности и формат результата. Доступ к инструментам проверяется сервером независимо от текста.</p><form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await command('instructions.save',{agentId:agent.id,text,version:agent.version});setSaved(true);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}}><FormField label="Инструкции агента"><textarea className="instruction-editor" value={text} onChange={e=>{setText(e.target.value);setSaved(false);}} required rows={16} maxLength={20000}/></FormField><FormMessage error={error}/><div className="inline"><button className="button primary" disabled={busy}>Сохранить новую версию</button>{saved&&<span className="success-text" role="status">Сохранено</span>}</div></form>{snapshot.instructionVersions?.filter((v:any)=>v.agentId===agent.id).length>0&&<details className="instruction-history"><summary>История версий</summary>{snapshot.instructionVersions.filter((v:any)=>v.agentId===agent.id).map((v:any)=><article key={v.id}><strong>Версия {v.version} · {date(v.createdAt)}</strong><pre>{v.text}</pre></article>)}</details>}</section>}
function Tools({agent,snapshot,command}:{agent:Agent;snapshot:Snapshot;command:Command}){const [permissions,setPermissions]=useState(agent.permissions);const [limits,setLimits]=useState(agent.limits);const [error,setError]=useState('');const tools=[{key:'materials.read',label:'Чтение материалов',description:'Разрешённые вложения и контекст задачи.',available:true},{key:'task.read',label:'Состояние задачи',description:'Этапы, сохранённые результаты и статус.',available:true},{key:'artifact.save',label:'Сохранение результата',description:'Текст, Markdown и фрагменты кода.',available:true},{key:'subtask.propose',label:'План подзадач',description:'Предложение ограниченного командного плана.',available:true},{key:'input.request',label:'Запрос уточнения',description:'Остановка до ответа владельца.',available:true},{key:'memory.propose',label:'Предложить правило',description:'Подготовка записи памяти к подтверждению.',available:true},{key:'memory.publish',label:'Публикация общей памяти',description:'Запись общего правила с проверкой полномочий.',available:true},{key:'github',label:'GitHub',description:'Интеграция с репозиториями не подключена.',available:false},{key:'browser',label:'Браузер',description:'Веб-инструмент не подключён.',available:false},{key:'shell',label:'Выполнение кода',description:'Изолированная среда не подключена.',available:false},{key:'email',label:'Почта',description:'Почтовый сервис не подключён.',available:false}];return <section className="panel-section"><h3>Инструменты и доступ</h3><p className="muted">Название роли не предоставляет доступ к внешним сервисам. Каждая операция проверяется на сервере.</p><form onSubmit={async e=>{e.preventDefault();setError('');try{await command('agents.update',{id:agent.id,version:agent.version,permissions,limits});}catch(e){setError((e as Error).message);}}}><div className="tool-list">{tools.map(t=><div className="tool-row" key={t.key}><span className={`tool-icon ${!t.available?'unavailable':''}`}><Icon name={t.available?'plug':'stop'}/></span><div><strong>{t.label}</strong><p>{t.description}</p>{!t.available&&<span className="subtle">Требуется настройка</span>}</div>{t.available?<select aria-label={`Доступ: ${t.label}`} value={permissions[t.key]||'deny'} onChange={e=>setPermissions({...permissions,[t.key]:e.target.value})}><option value="deny">Запрещено</option><option value="ask">Подтверждать</option><option value="allow">Разрешено</option></select>:<span className="chip setup">Недоступно</span>}</div>)}</div><h3>Параметры выполнения</h3><div className="form-grid agent-limits"><FormField label="Максимум шагов"><input type="number" min={1} max={10} value={limits.maxSteps} onChange={e=>setLimits({...limits,maxSteps:Number(e.target.value)})}/></FormField><FormField label="Бюджет токенов"><input type="number" min={100} max={100000} value={limits.maxTokens} onChange={e=>setLimits({...limits,maxTokens:Number(e.target.value)})}/></FormField></div><FormField label="Токенов в ответе"><input type="number" min={100} max={16000} value={limits.maxOutputTokens} onChange={e=>setLimits({...limits,maxOutputTokens:Number(e.target.value)})}/></FormField><FormMessage error={error}/><button className="button primary">Сохранить права и лимиты</button></form><div className="info-box"><Icon name="bookmark"/><p>Документы и ответы инструментов — входные материалы. Они не могут изменить права или системные ограничения.</p></div></section>}
function Activity({events}:{events:any[]}){return <div className="activity-list">{events.length===0?<Empty title="Пока нет событий" icon="history">Здесь появятся проверяемые действия, изменения и результаты.</Empty>:events.slice().reverse().map(e=><article className="activity-event" key={e.id}><span className="event-dot"/><div><strong>{e.summary||e.message||e.action||e.type}</strong>{e.tool&&<p className="mono subtle">{e.tool}</p>}{e.outcome&&<p>{e.outcome}</p>}<small>{date(e.createdAt)}{e.tokens?` · ${e.tokens} токенов`:''}</small></div></article>)}</div>}
interface DraftForm {title:string;description:string;expectedOutput:string;agentId:string;projectContext:string;projectId:string;priority:string;deadline:string;scheduledAt:string;maxSteps:number;maxTokens:number;teamPlan:string[];proposeMemory:string;inputRequested:boolean}
function TaskForm({snapshot,command,onDone}:{snapshot:Snapshot;command:Command;onDone:(id:string)=>void}){
 const defaults:DraftForm={title:'',description:'',expectedOutput:'',agentId:'auto',projectContext:'',projectId:'',priority:'normal',deadline:'',scheduledAt:'',maxSteps:10,maxTokens:12000,teamPlan:[],proposeMemory:'',inputRequested:false};const [form,setForm]=useState(defaults);const [search,setSearch]=useState('');const [step,setStep]=useState(1);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [files,setFiles]=useState<{id:string;name:string;status:string;error?:string}[]>([]);const [restored,setRestored]=useState(false);
 useEffect(()=>{try{const saved=sessionStorage.getItem('orvo-task-draft');const q=new URLSearchParams(location.search);setForm({...defaults,...(saved?JSON.parse(saved):{}),...(q.get('agent')?{agentId:q.get('agent')!}:{}),...(q.get('context')?{description:q.get('context')!}:{})});setRestored(true);}catch{setRestored(true);}},[]);
 useEffect(()=>{if(restored)sessionStorage.setItem('orvo-task-draft',JSON.stringify(form));},[form,restored]);
 const patch=(key:keyof DraftForm,value:unknown)=>setForm({...form,[key]:value});const agents=snapshot.agents.filter(a=>!a.archived&&`${a.name} ${a.role}`.toLowerCase().includes(search.toLowerCase()));const chosen=snapshot.agents.find(a=>a.id===form.agentId);const queue=(id:string)=>snapshot.tasks.filter(t=>t.agentId===id&&(ACTIVE_AGENT_TASK_STATUSES as readonly string[]).includes(t.status)&&!t.setupRequired).length;
 const create=async(draft=false)=>{setError('');setBusy(true);try{if(!form.title.trim()||!form.description.trim())throw new Error('Укажите название и описание задачи.');if(files.some(f=>f.status!=='ready'))throw new Error('Дождитесь проверки вложений или удалите файлы с ошибкой.');const result=await command('task.create',{...form,draft,scheduledAt:form.scheduledAt?localDateToUtc(form.scheduledAt,snapshot.settings.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone):undefined,deadline:form.deadline?localDateToUtc(form.deadline,snapshot.settings.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone):undefined,attachmentIds:files.map(f=>f.id)});sessionStorage.removeItem('orvo-task-draft');onDone(result.id||result.task?.id);}catch(e){setError((e as Error).message);}finally{setBusy(false);}};
 const upload=async(list:FileList|null)=>{if(!list)return;if(files.length+list.length>3){setError('Можно добавить не более трёх файлов.');return;}for(const file of Array.from(list)){if(file.size>10*1024*1024){setError(`${file.name}: размер превышает 10 МБ.`);continue;}const temporary=crypto.randomUUID();setFiles(prev=>[...prev,{id:temporary,name:file.name,status:'uploading'}]);try{const response=await fetch('/api/files',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:file.name,size:file.size,type:file.type||'text/plain'})});const permission=await response.json();if(!response.ok)throw new Error(permission.error?.message||'Загрузка недоступна');const id=permission.id;const uploaded=await fetch(permission.uploadUrl,{method:permission.method||'PUT',headers:permission.headers||{'Content-Type':file.type||'application/octet-stream'},body:file});if(!uploaded.ok){const failure=await uploaded.json().catch(()=>({}));throw new Error(failure.error?.message||'Не удалось загрузить файл');}setFiles(prev=>prev.map(f=>f.id===temporary?{...f,status:'processing'}:f));const completed=await fetch('/api/files',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:'complete',id})});const result=await completed.json();if(!completed.ok)throw new Error(result.error?.message||'Не удалось проверить файл');if(result.attachment?.status==='error')throw new Error(result.attachment.error||'Файл не прошёл проверку');setFiles(prev=>prev.map(f=>f.id===temporary?{id,name:file.name,status:result.attachment?.status||'ready'}:f));}catch(e){setFiles(prev=>prev.map(f=>f.id===temporary?{...f,status:'error',error:(e as Error).message}:f));}}};
 return <div className="task-form-layout"><section className="task-form card"><div className="form-steps"><button className={step===1?'active':''} onClick={()=>setStep(1)}><span>1</span>Задача и контекст</button><i/><button className={step===2?'active':''} onClick={()=>setStep(2)}><span>2</span>Проверка и запуск</button></div><form onSubmit={e=>{e.preventDefault();if(step===1)setStep(2);else create();}}>
 {step===1?<><div className="form-section"><div className="section-heading"><h2>Что нужно сделать?</h2><span className="subtle">Черновик сохраняется в этой вкладке</span></div><FormField label="Название задачи"><input value={form.title} onChange={e=>patch('title',e.target.value)} placeholder="Например, подготовить требования к MVP Orvo" required maxLength={200}/></FormField><FormField label="Описание" hint="Задача, исходные данные, важные ограничения."><textarea value={form.description} onChange={e=>patch('description',e.target.value)} placeholder="Расскажите, какого результата вы ждёте…" required rows={6} maxLength={24000}/></FormField><FormField label="Ожидаемый результат"><textarea value={form.expectedOutput} onChange={e=>patch('expectedOutput',e.target.value)} placeholder="Например: Markdown с требованиями и критериями приёмки" rows={3}/></FormField></div>
 <div className="form-section"><h2>Кто займётся задачей?</h2><label className="search-field"><Icon name="agents" size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Найти по имени или роли" aria-label="Найти исполнителя"/></label><div className="assignee-list" role="radiogroup" aria-label="Исполнитель"><button type="button" role="radio" aria-checked={form.agentId==='auto'} className={`assignee-option ${form.agentId==='auto'?'selected':''}`} onClick={()=>patch('agentId','auto')}><span className="auto-avatar"><Icon name="wave"/></span><span><strong>Автоматически</strong><small>Выберем подходящую роль с учётом модели и очереди</small></span><span className="radio-dot"/></button>{agents.map(a=><button type="button" role="radio" aria-checked={form.agentId===a.id} key={a.id} className={`assignee-option ${form.agentId===a.id?'selected':''}`} onClick={()=>patch('agentId',a.id)}><Avatar agent={a} size={32}/><span><strong>{a.name} <span className="subtle">· {a.role}</span></strong><small>{queue(a.id)?`В очереди и работе: ${queue(a.id)}`:(!modelReady(snapshot,a)?'Требуется настройка модели':'Готов к задаче')}</small></span><span className="radio-dot"/></button>)}</div></div>
 <div className="form-section"><h2>Контекст и материалы</h2><ProjectPicker snapshot={snapshot} command={command} value={form.projectId} onChange={value=>patch('projectId',value)}/><FormField label="Контекст проекта"><textarea value={form.projectContext} onChange={e=>patch('projectContext',e.target.value)} rows={3} placeholder="Аудитория, стек, принятые решения…"/></FormField><label className="upload-area"><Icon name="clip" size={24}/><strong>Добавить материалы</strong><span>TXT, Markdown или PDF с текстом · до 3 файлов по 10 МБ</span><input type="file" accept=".txt,.md,.markdown,.pdf" multiple onChange={e=>upload(e.target.files)} disabled={files.length>=3}/></label>{files.map(f=><div className={`upload-file ${f.status==='error'?'error':''}`} key={f.id}><Icon name="file"/><span><strong>{f.name}</strong><small>{f.status==='ready'?'Готово':f.status==='error'?f.error:f.status==='uploading'?'Загружается…':'Проверяется…'}</small></span><button className="icon-button" type="button" aria-label={`Удалить вложение ${f.name}`} onClick={()=>setFiles(files.filter(x=>x.id!==f.id))}><Icon name="x" size={16}/></button></div>)}</div>
 <div className="form-section"><h2>Порядок выполнения</h2><div className="form-grid"><FormField label="Приоритет"><select value={form.priority} onChange={e=>patch('priority',e.target.value)}><option value="low">Низкий</option><option value="normal">Обычный</option><option value="high">Высокий</option></select></FormField><FormField label="Срок результата"><input type="datetime-local" value={form.deadline} onChange={e=>patch('deadline',e.target.value)}/></FormField></div><FormField label="Отложенный запуск" hint={`Срок результата и время запуска — разные поля. Ваш часовой пояс: ${snapshot.workspace.timezone||snapshot.settings.timezone||'не задан'}.`}><input type="datetime-local" value={form.scheduledAt} onChange={e=>patch('scheduledAt',e.target.value)}/></FormField><details className="advanced-settings"><summary>Лимиты и командный план</summary><div className="form-grid"><FormField label="Максимум шагов"><input type="number" min={1} max={10} value={form.maxSteps} onChange={e=>patch('maxSteps',Number(e.target.value))}/></FormField><FormField label="Лимит токенов"><input type="number" min={100} max={100000} step={100} value={form.maxTokens} onChange={e=>patch('maxTokens',Number(e.target.value))}/></FormField></div><p className="subtle">Необязательный командный план: до трёх выбранных ролей, общий бюджет. Команда не запускается целиком.</p><FormField label="Предложить общее правило" hint="Внутренняя операция: публикация в память всей команды потребует отдельного подтверждения."><textarea value={form.proposeMemory} onChange={e=>patch('proposeMemory',e.target.value)} rows={2} maxLength={12000} placeholder="Необязательно: текст правила для команды"/></FormField><label className="checkbox input-request-option"><input type="checkbox" checked={form.inputRequested} onChange={e=>patch('inputRequested',e.target.checked)}/>Запросить уточнение перед выполнением</label><div className="team-options">{snapshot.agents.filter(a=>!a.archived).map(a=><label className="checkbox" key={a.id}><input type="checkbox" checked={form.teamPlan.includes(a.roleKey)} disabled={!form.teamPlan.includes(a.roleKey)&&form.teamPlan.length>=3} onChange={e=>patch('teamPlan',e.target.checked?[...form.teamPlan,a.roleKey]:form.teamPlan.filter(r=>r!==a.roleKey))}/>{a.name} · {a.role}</label>)}</div></details></div></>:<div className="form-section review-task"><span className="review-symbol"><Icon name="tasks" size={26}/></span><h2>Всё готово к поручению</h2><p className="muted">Проверьте задачу и ограничения перед запуском.</p><dl><dt>Задача</dt><dd>{form.title}</dd><dt>Описание</dt><dd className="preserve-text">{form.description}</dd><dt>Исполнитель</dt><dd>{chosen?`${chosen.name} · ${chosen.role}`:'Автоматический выбор по роли и доступности'}</dd><dt>Результат</dt><dd>{form.expectedOutput||'По описанию задачи'}</dd><dt>Лимиты</dt><dd>{form.maxSteps} шагов · {form.maxTokens.toLocaleString('ru-RU')} токенов</dd><dt>Начало</dt><dd>{form.scheduledAt?date(localDateToUtc(form.scheduledAt,snapshot.settings.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone)):'После сохранения и проверки сервером'}</dd><dt>Срок</dt><dd>{form.deadline?date(localDateToUtc(form.deadline,snapshot.settings.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone)):'Не задан'}</dd><dt>Командный план</dt><dd>{form.teamPlan.length?form.teamPlan.map(r=>snapshot.agents.find(a=>a.roleKey===r||a.id===r)?.role).join(' → '):'Один исполнитель'}</dd><dt>Материалы</dt><dd>{files.length?files.map(f=>f.name).join(', '):'Не приложены'}</dd></dl>{!modelReady(snapshot,chosen)&&<div className="warning-banner"><Icon name="plug"/><span>Модель ещё не настроена. Сервер сохранит задачу и сообщит о необходимой настройке.</span></div>}<p className="subtle">Работа выполняется на сервере. Цена может быть недоступна; лимиты проверяются перед каждым новым вызовом.</p></div>}
 <div className="form-actions"><FormMessage error={error}/><div className="inline"><button type="button" className="button secondary" onClick={()=>create(true)} disabled={busy||!form.title||!form.description}>Сохранить черновик</button><div className="flex-spacer"/>{step===2&&<button type="button" className="button secondary" onClick={()=>setStep(1)}>Назад</button>}<button className="button primary" disabled={busy||files.some(f=>f.status!=='ready')}>{busy?<span className="spinner small"/>:<Icon name={step===1?'tasks':'play'} size={17}/>} {step===1?'Проверить задачу':'Создать и запустить'}</button></div></div></form></section><aside className="task-form-aside"><div className="card"><span className="aside-icon"><Icon name="office" size={26}/></span><h3>Ясный запрос — хороший старт</h3><p>Опишите цель, приложите материалы и назовите ожидаемый результат.</p><div className="aside-divider"/><p><Icon name="check" size={16}/>История и результаты сохраняются</p><p><Icon name="agents" size={16}/>У каждого агента свои инструкции</p><p><Icon name="plug" size={16}/>Только доступные инструменты</p></div></aside></div>;
}
function TaskList({snapshot,openAgent}:{snapshot:Snapshot;openAgent:(id:string)=>void}){const [query,setQuery]=useState('');const [status,setStatus]=useState('all');const [agent,setAgent]=useState('all');const [page,setPage]=useState(0);const list=snapshot.tasks.filter(t=>(status==='all'||t.status===status)&&(agent==='all'||t.agentId===agent)&&`${t.title} ${t.description}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));const filtered=list.slice(page*12,(page+1)*12);return <><div className="filters"><label className="search-field"><Icon name="tasks" size={18}/><input aria-label="Поиск задач" placeholder="Найти задачу…" value={query} onChange={e=>{setQuery(e.target.value);setPage(0);}}/></label><select aria-label="Фильтр по статусу" value={status} onChange={e=>{setStatus(e.target.value);setPage(0);}}><option value="all">Все статусы</option>{Object.entries(STATUS).filter(([key])=>!['ready','idle','requires_setup','archived'].includes(key)).map(([key,s])=><option key={key} value={key}>{s.label}</option>)}</select><select aria-label="Фильтр по исполнителю" value={agent} onChange={e=>{setAgent(e.target.value);setPage(0);}}><option value="all">Все исполнители</option>{snapshot.agents.map(a=><option key={a.id} value={a.id}>{a.name} · {a.role}</option>)}</select></div><div className="task-count-line"><span>{list.length} задач</span><span>Обновление по серверному состоянию</span></div><div className="task-list card">{filtered.length?filtered.map(t=>{const a=snapshot.agents.find(a=>a.id===t.agentId);return <article className="task-row" key={t.id}><div className="task-row-status"><Icon name={(STATUS[t.status]||STATUS.draft).icon}/></div><div className="task-row-main"><a className="task-title" href={`/tasks/${t.id}`}>{t.title}</a><div className="task-row-meta">{a&&<button className="agent-inline" onClick={()=>openAgent(a.id)}><i style={{background:a.color}}/>{a.name} · {a.role}</button>}<span>{date(t.updatedAt)}</span>{t.teamPlan?.length>0&&<span>Команда · {t.teamPlan.length} ролей</span>}</div></div><Status value={t.status}/><a className="icon-button" href={`/tasks/${t.id}`} aria-label={`Открыть задачу ${t.title}`}><Icon name="expand" size={18}/></a></article>;}):<Empty title="Здесь начнётся работа команды" icon="tasks">{snapshot.tasks.length?'Измените фильтры, чтобы увидеть другие задачи.':<><p>Создайте первое поручение. Контекст, этапы и результаты останутся в одной задаче.</p><a href="/tasks/new" className="button primary"><Icon name="plus" size={16}/>Новая задача</a></>}</Empty>}</div>{list.length>12&&<div className="pagination"><button className="button secondary" disabled={page===0} onClick={()=>setPage(page-1)}>Назад</button><span>{page+1} / {Math.ceil(list.length/12)}</span><button className="button secondary" disabled={(page+1)*12>=list.length} onClick={()=>setPage(page+1)}>Далее</button></div>}</>}
function TaskDetails({task,snapshot,command,openAgent}:{task:Task;snapshot:Snapshot;command:Command;openAgent:(id:string)=>void}){const [revising,setRevising]=useState(false);const [comment,setComment]=useState('');const [cancel,setCancel]=useState(false);const [error,setError]=useState('');const agent=snapshot.agents.find(a=>a.id===task.agentId);const artifacts=snapshot.artifacts.filter(a=>a.taskId===task.id);const rawSteps=task.steps||snapshot.taskSteps?.filter((s:any)=>s.taskId===task.id)||[];const steps=Array.from(rawSteps.reduce((map:Map<string,any>,s:any)=>{const key=s.stage!==undefined?String(s.stage):s.stepKey||s.id;const previous=map.get(key);map.set(key,{...previous,...s,startedAt:previous?.startedAt||s.startedAt||s.createdAt});return map;},new Map<string,any>()).values()) as any[];const used=snapshot.usage.filter(u=>u.taskId===task.id);const taskSnapshot={...snapshot,approvals:snapshot.approvals.filter(a=>a.taskId===task.id)};const live=['running','queued','retry_scheduled','scheduled'].includes(task.status);return <><a href="/tasks" className="back-link">← Все задачи</a><div className="task-detail-grid"><div className="task-detail-main"><section className="card detail-section"><div className="section-heading"><Status value={task.status}/><span className="subtle mono">Версия {task.revision||1}</span></div><h2>{task.title}</h2><p className="preserve-text">{task.description}</p>{task.expectedOutput&&<div className="expected-result"><small>ОЖИДАЕМЫЙ РЕЗУЛЬТАТ</small><p>{task.expectedOutput}</p></div>}{task.projectContext&&<details><summary>Контекст проекта</summary><p className="preserve-text">{task.projectContext}</p></details>}<div className="task-controls">{(task.status==='draft'||(task.status==='waiting_for_input'&&task.setupRequired))&&<CommandButton command={command} type="task.start" payload={{id:task.id}} className="button primary"><Icon name="play" size={16}/>Запустить</CommandButton>}{live&&<CommandButton command={command} type="task.pause" payload={{id:task.id}}><Icon name="pause" size={16}/>Пауза</CommandButton>}{task.status==='paused'&&<CommandButton command={command} type="task.resume" payload={{id:task.id}} className="button primary"><Icon name="play" size={16}/>Продолжить</CommandButton>}{task.status==='failed'&&<CommandButton command={command} type="task.retry" payload={{id:task.id}} className="button primary"><Icon name="undo" size={16}/>Повторить</CommandButton>}{!['completed','cancelled','cancel_requested'].includes(task.status)&&<button className="button quiet danger" onClick={()=>setCancel(true)}><Icon name="stop" size={16}/>Отменить задачу</button>}</div>{['pause_requested','cancel_requested'].includes(task.status)&&<div className="info-box"><Icon name="clock"/><p>Завершаем текущий шаг. Новые действия будут остановлены на безопасной границе. Уже выполненные операции не отменяются.</p></div>}{task.setupRequired&&<div className="warning-banner"><Icon name="plug"/><span>Для запуска требуется настройка модели.</span><a href="/settings" className="text-link">Настроить</a></div>}{task.error&&<div className="error-detail"><h3><Icon name="warn"/>Не удалось завершить этап</h3><p>{typeof task.error==='string'?task.error:task.error.message||task.error.code}</p><p className="subtle">Сохранённые материалы остаются доступны. Проверьте подключение и лимиты перед повтором.</p></div>}</section>
 <Approvals snapshot={taskSnapshot} command={command}/>{task.status==='waiting_for_input'&&!task.setupRequired&&<TaskInput task={task} command={command}/>}<section className="card detail-section"><div className="section-heading"><h2>Этапы выполнения</h2><span className="subtle">{steps.filter((s:any)=>s.status==='completed').length} из {steps.length}</span></div>{steps.length?<ol className="task-stages">{steps.map((s:any,i:number)=><li className={s.status} key={s.id||i}><span className="stage-icon"><Icon name={s.status==='completed'?'check':s.status==='failed'?'warn':s.status==='running'?'run':'dots'} size={17}/></span><div><strong>{s.title||s.name||s.type||`Этап ${i+1}`}</strong><p>{s.summary||s.resultSummary||s.status}</p>{s.error&&<p className="danger">{typeof s.error==='string'?s.error:s.error.message}</p>}<small>{date(s.completedAt||s.startedAt||s.createdAt)}</small></div></li>)}</ol>:<p className="muted">Этапы появятся после фактического начала выполнения. Прогресс не симулируется.</p>}</section>
 <section className="card detail-section"><div className="section-heading"><h2>Готовые материалы</h2><span className="quiet-count">{artifacts.length}</span></div>{artifacts.length?artifacts.map(a=><Artifact artifact={a} agent={agent} key={a.id}/>):<p className="muted">Результаты ещё не сохранены.</p>}{task.status==='ready_for_review'&&<div className="result-review"><h3>Результат готов к просмотру</h3><p>Принятие сохранит текущую версию. Для правок укажите конкретный комментарий.</p><div className="inline"><CommandButton command={command} type="task.accept" payload={{id:task.id}} className="button success"><Icon name="check" size={17}/>Принять результат</CommandButton><button className="button secondary" onClick={()=>setRevising(!revising)}>Попросить правки</button></div>{revising&&<form className="revision-form" onSubmit={async e=>{e.preventDefault();try{await command('task.revise',{id:task.id,comment});setRevising(false);setComment('');}catch(e){setError((e as Error).message);}}}><FormField label="Что нужно изменить?"><textarea required rows={3} value={comment} onChange={e=>setComment(e.target.value)}/></FormField><FormMessage error={error}/><button className="button primary">Отправить на доработку</button></form>}</div>}</section>
 <section className="card"><div className="detail-section"><h2>Обсуждение задачи</h2></div>{agent&&<TaskChat agent={agent} task={task} snapshot={snapshot} command={command}/>}</section></div><aside className="task-detail-aside"><section className="card detail-section"><h3>Исполнитель</h3>{agent&&<button className="task-owner" onClick={()=>openAgent(agent.id)}><Avatar agent={agent}/><span><strong>{agent.name}</strong><small>{agent.role}</small></span><Icon name="expand" size={15}/></button>}<dl className="metadata-list"><dt>Создано</dt><dd>{date(task.createdAt)}</dd><dt>Обновлено</dt><dd>{date(task.updatedAt)}</dd><dt>Приоритет</dt><dd>{task.priority==='high'?'Высокий':task.priority==='low'?'Низкий':'Обычный'}</dd><dt>Запуск</dt><dd>{task.scheduledAt?date(task.scheduledAt):'Без отложенного старта'}</dd><dt>Срок</dt><dd>{task.deadline?date(task.deadline):'Не задан'}</dd><dt>Максимум шагов</dt><dd>{task.maxSteps}</dd><dt>Лимит токенов</dt><dd>{task.maxTokens?.toLocaleString('ru-RU')}</dd></dl></section><section className="card detail-section"><h3>Использование</h3><strong className="display usage-number">{used.reduce((v,u)=>v+(u.inputTokens||0)+(u.outputTokens||0),0).toLocaleString('ru-RU')}</strong><p className="subtle">учтённых токенов</p><p className="muted">Стоимость недоступна</p>{used.map(u=><div className="usage-row" key={u.id}><small>{u.model||'Модель'}</small><span className="mono">{(u.inputTokens||0)+(u.outputTokens||0)}</span></div>)}</section>{task.teamPlan?.length>0&&<section className="card detail-section"><h3>Командный план</h3><ol className="team-plan">{task.teamPlan.map((r:string)=><li key={r}>{snapshot.agents.find(a=>a.roleKey===r||a.id===r)?.role||r}</li>)}</ol><p className="subtle">Общий бюджет задачи. Одна ступень делегирования.</p>{snapshot.tasks.filter(t=>t.parentTaskId===task.id).map(t=><a key={t.id} className="mini-task" href={`/tasks/${t.id}`}><span>{t.title}</span><Status value={t.status}/></a>)}</section>}<section className="card detail-section"><h3>Журнал задачи</h3><Activity events={snapshot.events.filter(e=>e.taskId===task.id)}/></section></aside></div>{cancel&&<Dialog title="Отменить дальнейшую работу?" close={()=>setCancel(false)}><p className="muted">Новые шаги будут запрещены. Выполненные материалы сохранятся; уже выполненные внешние действия не откатываются.</p><div className="inline"><button className="button secondary" onClick={()=>setCancel(false)}>Продолжить задачу</button><button className="button danger-button" onClick={async()=>{try{await command('task.cancel',{id:task.id});setCancel(false);}catch{}}}>Отменить задачу</button></div></Dialog>}</>}
function TaskChat({agent,task,snapshot,command}:{agent:Agent;task:Task;snapshot:Snapshot;command:Command}){const [text,setText]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);const messages=snapshot.messages.filter(m=>m.taskId===task.id);return <><div className="chat-messages task-messages">{messages.map(m=><article className={`message ${m.role==='user'?'mine':'theirs'}`} key={m.id}><div className="message-author">{m.role==='user'?'Вы':agent.name}<time>{date(m.createdAt)}</time></div><p>{m.text||m.content}</p></article>)}{!messages.length&&<p className="muted">Вопросы и уточнения останутся в контексте этой задачи.</p>}</div><form className="chat-composer" onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await command('chat.send',{agentId:agent.id,taskId:task.id,text});setText('');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}}><FormField label="Уточнение к задаче"><textarea value={text} onChange={e=>setText(e.target.value)} rows={3} required maxLength={12000}/></FormField><p className="subtle">Активные уточнения будут доступны исполнителю на следующем подходящем шаге.</p><FormMessage error={error}/><button className="button primary" disabled={busy||!text.trim()}><Icon name="send" size={16}/>Сохранить сообщение</button></form></>}
function Artifact({artifact,agent}:{artifact:any;agent?:Agent}){const [open,setOpen]=useState(false);const [copied,setCopied]=useState(false);const [copyError,setCopyError]=useState('');const content=typeof artifact.text==='string'?artifact.text:typeof artifact.content==='string'?artifact.content:JSON.stringify(artifact.content||'',null,2);return <article className="artifact"><button className="artifact-header" onClick={()=>setOpen(!open)} aria-expanded={open}><span className="artifact-icon"><Icon name="file"/></span><span><strong>{artifact.filename||artifact.name||artifact.title||'Результат задачи'}</strong><small>{artifact.format||'Markdown'} · версия {artifact.version||1} · {agent?.name||'Агент'} · {date(artifact.createdAt)}</small></span><span className="chip done">{artifact.accepted?'Принято':'Сохранено'}</span><span>{open?'−':'+'}</span></button>{open&&<div className="artifact-preview"><pre>{content}</pre><div className="inline"><button className="button secondary" onClick={async()=>{try{await navigator.clipboard.writeText(content);setCopied(true);setTimeout(()=>setCopied(false),2000);}catch{setCopyError('Браузер запретил копирование. Выделите текст результата.');}}}><Icon name="file" size={16}/>{copied?'Скопировано':'Копировать'}</button><a className="button secondary" href={`/api/files/${artifact.id}`} download><Icon name="expand" size={16}/>Скачать</a></div>{copyError&&<p className="form-error">{copyError}</p>}</div>}</article>}
function History({snapshot}:{snapshot:Snapshot}){const [view,setView]=useState('tasks');const tasks=snapshot.tasks.filter(t=>['completed','cancelled','failed'].includes(t.status));return <><div className="panel-tabs history-tabs" role="tablist"><button role="tab" aria-selected={view==='tasks'} onClick={()=>setView('tasks')}>Завершённые задачи <span className="count">{tasks.length}</span></button><button role="tab" aria-selected={view==='events'} onClick={()=>setView('events')}>Журнал событий <span className="count">{snapshot.events.length}</span></button><button role="tab" aria-selected={view==='artifacts'} onClick={()=>setView('artifacts')}>Материалы <span className="count">{snapshot.artifacts.length}</span></button></div><section className="card history-content">{view==='events'?<Activity events={snapshot.events}/>:view==='artifacts'?snapshot.artifacts.length?snapshot.artifacts.slice().reverse().map(a=><Artifact artifact={a} agent={snapshot.agents.find(g=>g.id===a.agentId)} key={a.id}/>):<Empty title="Сохранённых материалов пока нет" icon="file">Готовые версии результатов появятся после выполнения задач.</Empty>:tasks.length?tasks.slice().reverse().map(t=><a className="history-task" key={t.id} href={`/tasks/${t.id}`}><span className="history-task-icon"><Icon name={t.status==='completed'?'check':t.status==='failed'?'warn':'stop'}/></span><span><strong>{t.title}</strong><small>{date(t.updatedAt)} · {snapshot.agents.find(a=>a.id===t.agentId)?.name}</small></span><Status value={t.status}/><Icon name="expand" size={16}/></a>):<Empty title="История начинается с первого результата" icon="history">Здесь сохраняются завершённые и отменённые задачи. Журнал содержит проверяемые действия.</Empty>}</section></>}
function Settings({snapshot,command}:{snapshot:Snapshot;command:Command}){const [error,setError]=useState('');const [saved,setSaved]=useState('');const [checking,setChecking]=useState(false);const [checkResult,setCheckResult]=useState<any>(null);const [provider,setProvider]=useState(snapshot.settings.provider||'gateway');const [model,setModel]=useState(snapshot.settings.model||'');const save=async(e:FormEvent<HTMLFormElement>,kind:string)=>{e.preventDefault();setError('');setSaved('');const f=Object.fromEntries(new FormData(e.currentTarget));try{const numberFields=['maxTokens','maxTaskTokens','maxSteps','maxConcurrent','maxOutputTokens','maxRetries'];const payload=Object.fromEntries(Object.entries(f).map(([k,v])=>[k,numberFields.includes(k)?Number(v):v]));await command('settings.save',payload);setSaved(kind);}catch(e){setError((e as Error).message);}};return <div className="settings-layout"><aside className="settings-nav"><a href="#profile" className="active"><Icon name="agents" size={17}/>Профиль</a><a href="#appearance"><Icon name="sun" size={17}/>Внешний вид</a><a href="#model"><Icon name="plug" size={17}/>Модель и подключение</a><a href="#limits"><Icon name="coins" size={17}/>Лимиты</a><a href="#integrations"><Icon name="server" size={17}/>Интеграции</a></aside><div className="settings-sections"><FormMessage error={error}/>{saved&&<div className="success-banner" role="status"><Icon name="check" size={17}/>{saved}: настройки сохранены.</div>}<section className="card detail-section" id="profile"><div className="settings-section-heading"><span className="settings-section-icon"><Icon name="agents"/></span><div><h2>Ваше рабочее пространство</h2><p>Личный офис одного владельца</p></div></div><form onSubmit={e=>save(e,'Профиль')}><FormField label="Имя владельца / пространства"><input name="name" defaultValue={snapshot.settings.name||snapshot.workspace.name||''} placeholder="Как к вам обращаться?" required maxLength={80}/></FormField><FormField label="Часовой пояс" hint="Сроки и расписание показываются в этом часовом поясе."><input name="timezone" defaultValue={snapshot.workspace.timezone||snapshot.settings.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone} required list="timezones"/><datalist id="timezones"><option value="Asia/Qyzylorda"/><option value="Asia/Almaty"/><option value="Europe/Moscow"/><option value="UTC"/></datalist></FormField><button className="button secondary">Сохранить профиль</button></form></section>
 <section className="card detail-section" id="appearance"><h2>Внешний вид</h2><div className="theme-options"><CommandButton command={command} type="settings.save" payload={{theme:'dark'}} className={`theme-option ${snapshot.settings.theme!=='light'?'selected':''}`}><span className="theme-preview dark-preview"><i/><i/><i/></span><span><Icon name="moon" size={17}/>Графитовая</span></CommandButton><CommandButton command={command} type="settings.save" payload={{theme:'light'}} className={`theme-option ${snapshot.settings.theme==='light'?'selected':''}`}><span className="theme-preview light-preview"><i/><i/><i/></span><span><Icon name="sun" size={17}/>Светлая</span></CommandButton></div><p className="subtle">Системная настройка уменьшения анимации учитывается автоматически.</p></section>
 <section className="card detail-section" id="model"><div className="section-heading"><h2>Модель и подключение</h2><Status value={provider===snapshot.settings.provider&&model===snapshot.settings.model&&modelReady(snapshot)?'ready':'requires_setup'}/></div><p className="muted">Ключ хранится в серверном окружении. Название модели само по себе не подтверждает доступность API.</p><form onSubmit={e=>save(e,'Подключение')}><FormField label="Провайдер"><select name="provider" value={provider} onChange={e=>{setProvider(e.target.value);setCheckResult(null);}}><option value="openai">OpenAI API (по ключу)</option><option value="gateway">Vercel AI Gateway</option>{snapshot.settings.testMode&&<option value="test">Тестовый провайдер (без модели)</option>}</select></FormField><ModelPicker key={provider} provider={provider} value={model} onChange={next=>{setModel(next);setCheckResult(null);}} testProvider={provider==='test'}/><div className="model-connection"><span className={`connection ${provider===snapshot.settings.provider&&snapshot.settings.credentialsConfigured?'connected':'offline'}`}><i/>{provider==='test'?'Тестовый режим':provider!==snapshot.settings.provider?'Подключение не проверено':snapshot.settings.credentialsConfigured?'Серверный ключ настроен':'Серверный ключ не настроен'}</span>{snapshot.settings.modelCheckAt&&<small>Последняя проверка: {date(snapshot.settings.modelCheckAt)}</small>}</div><div className="inline"><button className="button primary">Сохранить подключение</button><button className="button secondary" type="button" disabled={checking} onClick={async()=>{setChecking(true);setError('');try{await command('settings.save',{model,provider});const result=await command('settings.checkModel',{});setCheckResult(result);}catch(e){setError((e as Error).message);}finally{setChecking(false);}}}>{checking?<span className="spinner small"/>:<Icon name="plug" size={16}/>}Проверить модель</button></div>{checkResult&&<p className={checkResult.ok||checkResult.available?'success-text':'muted'} role="status">{checkResult.message||JSON.stringify(checkResult)}</p>}</form>{provider==='test'&&<div className="test-banner"><Icon name="warn"/><span>Тестовый провайдер проверяет серверный путь и не создаёт настоящие ответы ИИ. Рабочие и тестовые данные разделены сервером.</span></div>}</section>
 <section className="card detail-section" id="limits"><h2>Границы выполнения</h2><p className="muted">Лимиты проверяются на сервере перед новым вызовом. Уже отправленный запрос может повлиять на окончательный расход.</p><form onSubmit={e=>save(e,'Лимиты')}><div className="form-grid"><FormField label="Общий лимит токенов"><input name="maxTokens" type="number" min={100} max={10000000} defaultValue={snapshot.settings.maxTokens||100000}/></FormField><FormField label="Шагов на задачу"><input name="maxSteps" type="number" min={1} max={10} defaultValue={snapshot.settings.maxSteps||10}/></FormField><FormField label="Лимит токенов задачи"><input name="maxTaskTokens" type="number" min={100} max={100000} defaultValue={snapshot.settings.maxTaskTokens||24000}/></FormField><FormField label="Токенов в ответе"><input name="maxOutputTokens" type="number" min={100} max={16000} defaultValue={snapshot.settings.maxOutputTokens||4000}/></FormField></div><button className="button secondary">Сохранить лимиты</button></form><p className="subtle">Стоимость недоступна без подтверждённых тарифных данных. Токены отражают сохранённый учёт провайдера.</p></section>
 <section className="card detail-section" id="integrations"><h2>Интеграции</h2><p className="muted">Внешние действия доступны после отдельного подключения соответствующего инструмента.</p>{[['GitHub','Работа с репозиториями'],['Ritm','Будущая связь с планировщиком через API'],['Браузер и поиск','Получение внешних материалов'],['Изолированная среда','Запуск кода'],['Почта и уведомления','Email, Telegram и push']].map(([name,description])=><div className="integration-row" key={name}><span className="tool-icon"><Icon name="plug"/></span><div><strong>{name}</strong><p>{description}</p></div><span className="chip setup">Не подключено</span></div>)}<div className="info-box"><Icon name="bell"/><p>Сейчас работает серверный inbox внутри Orvo. Доставка уведомлений на устройство без открытой вкладки не подключена.</p></div></section><section className="card detail-section"><h2>Сессия</h2><p className="muted">Закрытый доступ владельца. Публичная регистрация отсутствует.</p><button className="button secondary" onClick={async()=>{await fetch('/api/auth/sign-out',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});location.assign('/login');}}>Выйти из пространства</button></section></div></div>}

export default OrvoApp;
function ProjectPicker({snapshot,command,value,onChange,required=false}:{snapshot:Snapshot;command:Command;value:string;onChange:(value:string)=>void;required?:boolean}){const [adding,setAdding]=useState(false);const [name,setName]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);return <div className="project-picker"><FormField label={required?'Проект':'Проект (необязательно)'}><select value={value} onChange={e=>onChange(e.target.value)} required={required}><option value="">{required?'Выберите проект':'Без отдельного проекта'}</option>{snapshot.projects?.map((p:any)=><option key={p.id} value={p.id}>{p.name||p.title}</option>)}</select></FormField>{adding?<div className="new-project inline"><input aria-label="Название нового проекта" value={name} onChange={e=>setName(e.target.value)} placeholder="Название проекта" maxLength={100}/><button className="button secondary" type="button" disabled={busy||!name.trim()} onClick={async()=>{setBusy(true);setError('');try{const result=await command('project.save',{name:name.trim()});onChange(result.id);setAdding(false);setName('');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}}>Создать</button><button className="icon-button" type="button" aria-label="Отменить создание проекта" onClick={()=>setAdding(false)}><Icon name="x" size={16}/></button></div>:<button type="button" className="text-link" onClick={()=>setAdding(true)}><Icon name="plus" size={13}/>Добавить проект</button>}<FormMessage error={error}/></div>}
function TaskInput({task,command}:{task:Task;command:Command}){const [answer,setAnswer]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);return <section className="card detail-section task-input"><h3><Icon name="alert" size={17}/> Нужен ваш ответ</h3><p className="muted">{task.inputPrompt||'Уточните исходные данные или подтвердите, что текущего описания достаточно.'}</p><form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await command('task.resume',{id:task.id,comment:answer});setAnswer('');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}}><FormField label="Ответ исполнителю"><textarea required rows={3} maxLength={12000} value={answer} onChange={e=>setAnswer(e.target.value)}/></FormField><FormMessage error={error}/><button className="button primary" disabled={busy}><Icon name="play" size={16}/>Отправить ответ и продолжить</button></form></section>}
function RelatedMemories({text,memories}:{text:string;memories:MemoryRecord[]}){const words=text.toLowerCase().match(/[а-яa-z]{5,}/g)||[];if(!words.length)return null;const related=memories.filter(m=>words.some(w=>m.text.toLowerCase().includes(w))).slice(0,3);return related.length?<div className="related-memory"><strong>Связанные записи</strong><p>Перед сохранением проверьте, нет ли противоречий.</p>{related.map(m=><blockquote key={m.id}>{m.text}</blockquote>)}</div>:null;}
